... đường dữ liệu (datapath) từ Hình 7.15 và bộ điều khiển (controller) từ Hình 7.16. Bộ điều khiển, đến lượt nó, lại được cấu thành từ Bộ giải mã chính (Main Decoder) và Bộ giải mã ALU (ALU Decoder).

Mã HDL được phân chia thành nhiều phần. Mục 7.6.1 cung cấp mã HDL cho đường dữ liệu và bộ điều khiển của bộ xử lý đơn chu kỳ (single-cycle processor). Mục 7.6.2 trình bày các khối xây dựng cơ bản (generic building blocks), chẳng hạn như các thanh ghi và bộ dồn kênh (multiplexer), vốn được sử dụng bởi bất kỳ vi kiến trúc nào. Mục 7.6.3 giới thiệu chương trình kiểm thử (test program), môi trường kiểm thử (testbench) và các bộ nhớ ngoài. Mã HDL và chương trình kiểm thử hiện có sẵn dưới dạng tệp điện tử trên trang web của cuốn sách này (xem phần Lời nói đầu).

7.6.1 Bộ xử lý đơn chu kỳ
Các module chính của mô-đun bộ xử lý đơn chu kỳ được trình bày trong các ví dụ HDL sau đây.

Ví dụ HDL 7.1 BỘ XỬ LÝ ĐƠN CHU KỲ

[SystemVerilog]
module riscvsingle(input logic clk, reset,
                    output logic [31:0] PC,
                    input logic [31:0] Instr,
                    output logic MemWrite,
                    output logic [31:0] ALUResult, WriteData,
                    input logic [31:0] ReadData);

  logic ALUSrc, RegWrite, Jump, Zero;
  logic [1:0] ResultSrc, ImmSrc;
  logic [2:0] ALUControl;

  controller c(Instr[6:0], Instr[14:12], Instr[30], Zero,
               ResultSrc, MemWrite, PCSrc,
               ALUSrc, RegWrite, Jump,
               ImmSrc, ALUControl);
  datapath dp(clk, reset, ResultSrc, PCSrc,
              ALUSrc, RegWrite,
              ImmSrc, ALUControl,
              Zero, PC, Instr,
              ALUResult, WriteData, ReadData);
endmodule

[VHDL]
library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity riscvsingle is
  port(clk, reset: in STD_LOGIC;
       PC: out STD_LOGIC_VECTOR(31 downto 0);
       Instr: in STD_LOGIC_VECTOR(31 downto 0);
       MemWrite: out STD_LOGIC;
       ALUResult, WriteData: out STD_LOGIC_VECTOR(31 downto 0);
       ReadData: in STD_LOGIC_VECTOR(31 downto 0));
end;

architecture struct of riscvsingle is
  component controller
    port(op: in STD_LOGIC_VECTOR(6 downto 0);
         funct3: in STD_LOGIC_VECTOR(2 downto 0);
         funct7b5, Zero: in STD_LOGIC;
         ResultSrc: out STD_LOGIC_VECTOR(1 downto 0);
         MemWrite: out STD_LOGIC;
         PCSrc, ALUSrc: out STD_LOGIC;
         RegWrite, Jump: out STD_LOGIC;
         ImmSrc: out STD_LOGIC_VECTOR(1 downto 0);
         ALUControl: out STD_LOGIC_VECTOR(2 downto 0));
  end component;
  component datapath
    port(clk, reset: in STD_LOGIC;
         ResultSrc: in STD_LOGIC_VECTOR(1 downto 0);
         PCSrc, ALUSrc: in STD_LOGIC;
         RegWrite: in STD_LOGIC;
         ImmSrc: in STD_LOGIC_VECTOR(1 downto 0);
         ALUControl: in STD_LOGIC_VECTOR(2 downto 0);
         Zero: out STD_LOGIC;
         PC: out STD_LOGIC_VECTOR(31 downto 0);
         Instr: in STD_LOGIC_VECTOR(31 downto 0);
         ALUResult, WriteData: out STD_LOGIC_VECTOR(31 downto 0);
         ReadData: in STD_LOGIC_VECTOR(31 downto 0));
  end component;

