### **Ví dụ HDL 7.3: BỘ GIẢI MÃ CHÍNH (MAIN DECODER)**

#### **SystemVerilog**
module maindec(input  logic [6:0] op,
               output logic [1:0] ResultSrc,
               output logic       MemWrite,
               output logic       Branch, ALUSrc,
               output logic       RegWrite, Jump,
               output logic [1:0] ImmSrc,
               output logic [1:0] ALUOp);
  logic [10:0] controls;

  assign {RegWrite, ImmSrc, ALUSrc, MemWrite,
          ResultSrc, Branch, ALUOp, Jump} = controls;

  always_comb
    case(op)
      // RegWrite_ImmSrc_ALUSrc_MemWrite_ResultSrc_Branch_ALUOp_Jump
      7'b0000011: controls = 11'b1_00_1_0_01_0_00_0; // lw (đọc từ bộ nhớ)
      7'b0100011: controls = 11'b0_01_1_1_00_0_00_0; // sw (ghi vào bộ nhớ)
      7'b0110011: controls = 11'b1_xx_0_0_00_0_10_0; // Lệnh kiểu R
      7'b1100011: controls = 11'b0_10_0_0_00_1_01_0; // beq (nhảy nếu bằng)
      7'b0010011: controls = 11'b1_00_1_0_00_0_10_0; // Lệnh ALU kiểu I
      7'b1101111: controls = 11'b1_11_x_0_10_0_xx_1; // jal (nhảy và liên kết)
      default:    controls = 11'bx_xx_x_x_xx_x_xx_x; // Không hợp lệ / ???
    endcase
endmodule

#### **VHDL**
library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity maindec is
  port(op:        in  STD_LOGIC_VECTOR(6 downto 0);
       ResultSrc: out STD_LOGIC_VECTOR(1 downto 0);
       MemWrite:  out STD_LOGIC;
       Branch, ALUSrc: out STD_LOGIC;
       RegWrite, Jump: out STD_LOGIC;
       ImmSrc:    out STD_LOGIC_VECTOR(1 downto 0);
       ALUOp:     out STD_LOGIC_VECTOR(1 downto 0));
end;

architecture behave of maindec is
  signal controls: STD_LOGIC_VECTOR(10 downto 0);
begin
  process(op) begin
    case op is
      when "0000011" => controls <= "10010010000"; -- lw
      when "0100011" => controls <= "00111000000"; -- sw
      when "0110011" => controls <= "1--00000100"; -- Lệnh kiểu R
      when "1100011" => controls <= "01000001010"; -- beq
      when "0010011" => controls <= "10010000100"; -- Lệnh ALU kiểu I
      when "1101111" => controls <= "11100100001"; -- jal
      when others    => controls <= "-----------"; -- Không hợp lệ
    end case;
  end process;

  (RegWrite, ImmSrc(1), ImmSrc(0), ALUSrc, MemWrite,
   ResultSrc(1), ResultSrc(0), Branch, ALUOp(1), ALUOp(0),
   Jump) <= controls;
end;

