### **Ví dụ HDL 7.4: BỘ GIẢI MÃ ALU (ALU DECODER)**

#### **SystemVerilog**
module aludec(input  logic       opb5,
              input  logic [2:0] funct3,
              input  logic       funct7b5,
              input  logic [1:0] ALUOp,
              output logic [2:0] ALUControl);

  logic RtypeSub;
  assign RtypeSub = funct7b5 & opb5; // ĐÚNG đối với phép trừ kiểu R

  always_comb
    case(ALUOp)
      2'b00:                ALUControl = 3'b000; // Phép cộng
      2 meb01:              ALUControl = 3'b001; // Phép trừ
      default: case(funct3) // Lệnh ALU kiểu R hoặc kiểu I
                 3'b000: if (RtypeSub)
                           ALUControl = 3'b001; // Phép trừ
                         else
                           ALUControl = 3'b000; // Phép cộng
                 3'b010:   ALUControl = 3'b101; // slt (so sánh bé hơn)
                 3'b110:   ALUControl = 3'b011; // Phép OR
                 3'b111:   ALUControl = 3'b010; // Phép AND
                 default:  ALUControl = 3'bxxx; // ???
               endcase
    endcase
endmodule

#### **VHDL**
library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity aludec is
  port(opb5:       in  STD_LOGIC;
       funct3:     in  STD_LOGIC_VECTOR(2 downto 0);
       funct7b5:   in  STD_LOGIC;
       ALUOp:      in  STD_LOGIC_VECTOR(1 downto 0);
       ALUControl: out STD_LOGIC_VECTOR(2 downto 0));
end;

architecture behave of aludec is
  signal RtypeSub: STD_LOGIC;
begin
  RtypeSub <= funct7b5 and opb5; -- ĐÚNG đối với phép trừ kiểu R
  process(opb5, funct3, funct7b5, ALUOp, RtypeSub) begin
    case ALUOp is
      when "00" => ALUControl <= "000"; -- Phép cộng
      when "01" => ALUControl <= "001"; -- Phép trừ
      when others =>
        case funct3 is
          when "000" =>
            if RtypeSub = '1' then
              ALUControl <= "001"; -- Phép trừ
            else
              ALUControl <= "000"; -- Phép cộng
            end if;
          when "010" => ALUControl <= "101"; -- slt
          when "110" => ALUControl <= "011"; -- Phép OR
          when "111" => ALUControl <= "010"; -- Phép AND
          when others => ALUControl <= "---";
        end case;
    end case;
  end process;
end;

