Ví dụ HDL 7.7 KHỐI MỞ RỘNG (EXTEND UNIT)

SystemVerilog
module extend(input logic [31:7] instr,
              input logic [1:0] immsrc,
              output logic [31:0] immext);

  always_comb
    case(immsrc)
      // Dạng I (I-type)
      2'b00: immext = {{20{instr[31]}}, instr[31:20]};
      // Dạng S (lưu trữ - stores)
      2'b01: immext = {{20{instr[31]}}, instr[31:25],
                       instr[11:7]};
      // Dạng B (nhánh - branches)
      2'b10: immext = {{20{instr[31]}}, instr[7],
                       instr[30:25], instr[11:8], 1'b0};
      // Dạng J (nhảy - jal)
      2'b11: immext = {{12{instr[31]}}, instr[19:12],
                       instr[20], instr[30:21], 1'b0};
      default: immext = 32'bx; // chưa xác định
    endcase
endmodule

VHDL
library IEEE;
use IEEE.STD_LOGIC_1164.all;

entity extend is
  port(instr: in STD_LOGIC_VECTOR(31 downto 7);
       immsrc: in STD_LOGIC_VECTOR(1 downto 0);
       immext: out STD_LOGIC_VECTOR(31 downto 0));
end;

architecture behave of extend is
begin
  process(instr, immsrc) begin
    case immsrc is
      -- Dạng I (I-type)
      when "00" =>
        immext <= (31 downto 12 => instr(31)) & instr(31 downto 20);
      -- Dạng S (lưu trữ - stores)
      when "01" =>
        immext <= (31 downto 12 => instr(31)) &
                  instr(31 downto 25) & instr(11 downto 7);
      -- Dạng B (nhánh - branches)
      when "10" =>
        immext <= (31 downto 12 => instr(31)) & instr(7) & instr(30
                  downto 25) & instr(11 downto 8) & '0';
      -- Dạng J (nhảy - jal)
      when "11" =>
        immext <= (31 downto 20 => instr(31)) &
                  instr(19 downto 12) & instr(20) &
                  instr(30 downto 21) & '0';
      when others =>
        immext <= (31 downto 0 => '-');
    end case;
  end process;
end;

Ví dụ HDL 7.8 FLIP-FLOP CÓ KHẢ NĂNG RESET (RESETTABLE FLIP-FLOP)

SystemVerilog
module flopr #(parameter WIDTH = 8)
              (input logic clk, reset,
               input logic [WIDTH-1:0] d,
               output logic [WIDTH-1:0] q);

  always_ff @(posedge clk, posedge reset)
    if (reset) q <= 0;
    else q <= d;
endmodule

VHDL
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.STD_LOGIC_ARITH.all;

entity flopr is
  generic(width: integer);
  port(clk, reset: in STD_LOGIC;
       d: in STD_LOGIC_VECTOR(width-1 downto 0);
       q: out STD_LOGIC_VECTOR(width-1 downto 0));
end;

