-- khởi tạo bộ nhớ từ tập tin
impure function init_ram_hex return ramtype is
  file text_file : text open read_mode is "riscvtest.txt";
  variable text_line : line;
  variable ram_content : ramtype;
  variable i : integer := 0;
begin
  for i in 0 to 63 loop -- đặt tất cả nội dung về mức thấp
    ram_content(i) := (others => '0');
  end loop;
  while not endfile(text_file) loop -- thiết lập nội dung từ tập tin
    readline(text_file, text_line);
    hread(text_line, ram_content(i));
    i := i + 1;
  end loop;

  return ram_content;
end function;

signal mem : ramtype := init_ram_hex;
begin
  -- đọc bộ nhớ
  process(a) begin
    rd <= mem(to_integer(a(31 downto 2)));
  end process;
end;


